lines+=['',f'Equal-image arithmetic mean of the point estimates: {mean:.2f} m ({mean/.3048:.1f} ft); round to **about 4.2 m / 14 ft**. The input uncertainty is much larger than the hundredths in the computed mean.','','The two room images without any independent furniture or book scale cue are inferential cross-checks, not independent absolute scale measurements. AI/concept-art proportions and wide-angle perspective prevent precise recovery of real dimensions.','',report['other_references'],'','## Reasoning per image','']
for r in rows:lines += [f"**{r['label']}** (`{r['file']}`)",r['basis'],'']
